    categories:["Greater East Asia Economic Board","Japanese economic planning","GEACPS","Nobusuke Kishi"],
    facts:[["Established","1948 consolidation"],["Common Japanese rendering","Daitōa Keizai-in"],["Headquarters","Tokyo"],["Plans","Five- and ten-year imperial programs"],["Primary instruments","Credit, shipping, foreign exchange, concessions, guarantees"],["Development lender","Imperial Development Bank"]]
