    categories:["Greater East Asia Prosperity Plan","Hayato Ikeda","Japanese economic history","GEACPS development"],
    facts:[["Period","1960–1965"],["Prime minister","Hayato Ikeda"],["Planning authority","Greater East Asia Economic Board"],["Core doctrine","Prosperity is the proof of imperial peace"],["Principal showcase","Philippine Republic"],["Economic model","Hierarchical industrial ladder"]]
