    categories:["Japanese Pacific Territories","Micronesia","Melanesia","Polynesia","Japanese Empire"],
    facts:[["Metropolitan power","Empire of Japan"],["Older core","Former South Seas Mandate"],["Later possessions","Bismarcks to Tahiti"],["Nationality","Japanese after staged incorporation"],["Associated exception","Papua New Guinea"],["Principal external enclaves","American, Commonwealth, Portuguese, Tongan, and Chilean possessions"]]
